// Assume T is float or double
const int kMaxBins = 64; // Assuming a maximum number of bins
const int kNumAxis = 3;  // x, y, z

float minCost = std::numeric_limits<float>::max();
int bestAxis = 0;
bool found = false;

// Surface Area Heuristic cost
float S = (bmax[0] - bmin[0]) * (bmax[1] * (bmax[2] - bmin[2]) + 
          (bmax[1] - bmin[1]) * (bmax[2] - bmin[2]) + 
          (bmax[0] - bmin[0]) * (bmax[1] - bmin[1]));

for (int axis = 0; axis < kNumAxis; axis++) {
    float invSpan = 1.0f / (bmax[axis] - bmin[axis]);

    // Reset bins
    for (int i = 0; i < kMaxBins; i++) {
        bins->ClearBin(i);
    }

    // Distribute primitives to bins
    for (int i = 0; i < bins->GetNumPrimitives(); i++) {
        float3 bminPrim, bmaxPrim;
        bins->GetGeometry()->BoundingBox(&bminPrim, &bmaxPrim, bins->GetPrimitiveIndex(i));
        float center = (bminPrim[axis] + bmaxPrim[axis]) * 0.5f;
        int binId = (int)((center - bmin[axis]) * invSpan * kMaxBins);
        binId = std::min(binId, kMaxBins - 1);
        binId = std::max(binId, 0);
        bins->AddPrimitiveToBin(binId, i);
    }

    // Calculate cost for each split position
    for (int i = 0; i < kMaxBins - 1; i++) {
        int numLeft = 0;
        int numRight = 0;
        float leftExtent = 0.0f;
        float rightExtent = 0.0f;

        // Count primitives and calculate extents
        for (int j = 0; j <= i; j++) {
            numLeft += bins->GetBinSize(j);
            leftExtent += bins->GetBinExtent(j);
        }
        for (int j = i + 1; j < kMaxBins; j++) {
            numRight += bins->GetBinSize(j);
            rightExtent += bins->GetBinExtent(j);
        }

        // Calculate SAH cost
        float leftArea = leftExtent * (bmax[(axis + 1) % 3] - bmin[(axis + 1) % 3]) * 
                         (bmax[(axis + 2) % 3] - bmin[(axis + 2) % 3]);
        float rightArea = rightExtent * (bmax[(axis + 1) % 3] - bmin[(axis + 1) % 3]) * 
                          (bmax[(axis + 2) % 3] - bmin[(axis + 2) % 3]);

        float cost = leftArea * numLeft + rightArea * numRight;

        if (cost < minCost) {
            minCost = cost;
            bestAxis = axis;
            cut_pos[0] = bmin[0] + (float)(i + 1) / kMaxBins * (bmax[0] - bmin[0]);
            cut_pos[1] = bmin[1] + (float)(i + 1) / kMaxBins * (bmax[1] - bmin[1]);
            cut_pos[2] = bmin[2] + (float)(i + 1) / kMaxBins * (bmax[2] - bmin[2]);
            found = true;
        }
    }
}

*minCostAxis = bestAxis;
return found;

